Object.assign(SNIP,{});PRESET_NOTES["l39"]={"Ví dụ: Thêm và tìm từ": "4 từ chỉ tốn 9 nút (tính cả gốc) vì “cat”, “car”, “cart” dùng chung “c”, “ca”. Tìm: car có; ca không (chỉ là tiền tố, het = 0); cart có; cow không (sau “c” không có nhánh “o”).", "Ví dụ: Đếm số từ có một tiền tố": "dem[u] là số từ đi qua nút u, tính cả từ trùng. Có 4 từ bắt đầu bằng “an” (an, ant, anh, anh), 2 từ “anh”, 1 từ bắt đầu bằng “b”, 0 từ bắt đầu bằng “c”.", "Ví dụ: Liệt kê theo thứ tự từ điển": "Duyệt trước, thử các ký tự từ a đến z: các từ ra theo thứ tự từ điển mà không cần sắp xếp. Một từ in ra trước các từ dài hơn nhận nó làm tiền tố: i in inn tea ted ten to.", "Ví dụ: Trie nhị phân và XOR lớn nhất": "Bit cao quyết định trước: được bit 1 ở vị trí cao luôn lợi hơn mọi bit thấp cộng lại, nên ở mỗi tầng tham lam chọn nhánh ngược nếu có. Cặp tốt nhất là 5 (00101) và 25 (11001): XOR = 28 (11100).", "Lỗi: quên dấu kết thúc từ": "Từ điển chỉ có “cart” nhưng tim(\"car\") trả về đúng, vì đường c-a-r có trong cây. Cần dấu het[u] để biết có từ kết thúc đúng tại nút cuối."};EX_HINTS["l39"]=[["Khi thêm từ, mỗi nút đi qua tăng dem[u] thêm 1. Khi đó dem[u] là số từ có tiền tố ứng với u.", "Đếm cho tiền tố t: đi theo t từ gốc; gặp ô 0 thì đáp án 0, đi hết thì đáp án dem[u].", "Gọi taoNut() rồi mới gán vào nxt[u][c]: push_back có thể làm vector cấp phát lại, viết nxt[u][c] = taoNut() là nguy hiểm."], ["Thêm mọi số vào trie (bảng chữ 10 chữ số), dem[u] là số số đi qua nút u.", "a[i] là tiền tố của một số khác (hoặc trùng với số khác) khi và chỉ khi nút cuối của a[i] có dem > 1.", "Cách khác cũng đủ nhanh: sắp xếp các chuỗi, chỉ cần so mỗi chuỗi với chuỗi liền sau."], ["Cất các số vào trie nhị phân từ bit 29 xuống bit 0.", "Với số x: ở mỗi bit, nếu có nhánh mang bit ngược với bit của x thì đi nhánh đó (bit này của XOR là 1); không thì đi nhánh cùng bit.", "Xử lý lần lượt: tìm XOR lớn nhất của a[i] với các số trước nó rồi mới thêm a[i]. Cả bài O(30·n)."]];
/* ===================== BÀI 39 · Cây tiền tố (trie) ===================== */
/* Bài 39 · Cây tiền tố (trie)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR39=[{label:"Ví dụ: Thêm và tìm từ",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint nxt[20][26], het[20], soNut = 1;   // nút 0 là gốc\n\nvoid them(string s) {\n    int u = 0;\n    for (char ch : s) {\n        int c = ch - 'a';\n        if (nxt[u][c] == 0) nxt[u][c] = soNut++;   // tạo nút mới\n        u = nxt[u][c];\n    }\n    het[u] = 1;                        // có một từ kết thúc ở u\n}\n\nbool tim(string s) {\n    int u = 0;\n    for (char ch : s) {\n        int c = ch - 'a';\n        if (nxt[u][c] == 0) return false;          // đường bị đứt\n        u = nxt[u][c];\n    }\n    return het[u] == 1;\n}\n\nint main() {\n    them(\"cat\"); them(\"car\"); them(\"cart\"); them(\"dog\");\n    cout << tim(\"car\") << \" \" << tim(\"ca\") << \" \" << tim(\"cart\") << \" \" << tim(\"cow\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"het",ptr:["u"],range:["0","soNut-1"]}],py:{code:"nxt = [[0] * 26]               # nút 0 là gốc; nxt[u][c] = 0: chưa có con\nhet = [0]\n\ndef them(s):\n    u = 0\n    for ch in s:\n        c = ord(ch) - ord('a')\n        if nxt[u][c] == 0:             # tạo nút mới\n            nxt.append([0] * 26)\n            het.append(0)\n            nxt[u][c] = len(nxt) - 1\n        u = nxt[u][c]\n    het[u] = 1                         # có một từ kết thúc ở u\n\ndef tim(s):\n    u = 0\n    for ch in s:\n        c = ord(ch) - ord('a')\n        if nxt[u][c] == 0:             # đường bị đứt\n            return False\n        u = nxt[u][c]\n    return het[u] == 1\n\nfor w in [\"cat\", \"car\", \"cart\", \"dog\"]:\n    them(w)\nprint(tim(\"car\"), tim(\"ca\"), tim(\"cart\"), tim(\"cow\"))",viz:[{type:"cells",of:"het",ptr:["u"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static int[][] nxt = new int[20][];    // nút 0 là gốc; nxt[u][c] = 0: chưa có con\n    static int[] het = new int[20];\n    static int soNut = 1;\n\n    static void Them(string s)\n    {\n        int u = 0;\n        foreach (char ch in s)\n        {\n            int c = ch - 'a';\n            if (nxt[u][c] == 0) nxt[u][c] = soNut++;   // tạo nút mới\n            u = nxt[u][c];\n        }\n        het[u] = 1;                        // có một từ kết thúc ở u\n    }\n\n    static bool Tim(string s)\n    {\n        int u = 0;\n        foreach (char ch in s)\n        {\n            int c = ch - 'a';\n            if (nxt[u][c] == 0) return false;          // đường bị đứt\n            u = nxt[u][c];\n        }\n        return het[u] == 1;\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 20; i++) nxt[i] = new int[26];\n        foreach (string w in new[] { \"cat\", \"car\", \"cart\", \"dog\" }) Them(w);\n        Console.WriteLine(Tim(\"car\") + \" \" + Tim(\"ca\") + \" \" + Tim(\"cart\") + \" \" + Tim(\"cow\"));\n    }\n}",viz:[{type:"cells",of:"het",ptr:["u"],range:["0","soNut-1"]}]}},{label:"Ví dụ: Đếm số từ có một tiền tố",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint nxt[20][26], dem[20], soNut = 1;\n\nvoid them(string s) {\n    int u = 0;\n    for (char ch : s) {\n        int c = ch - 'a';\n        if (nxt[u][c] == 0) nxt[u][c] = soNut++;\n        u = nxt[u][c];\n        dem[u]++;                      // thêm một từ đi qua u\n    }\n}\n\nint demTienTo(string s) {\n    int u = 0;\n    for (char ch : s) {\n        int c = ch - 'a';\n        if (nxt[u][c] == 0) return 0;\n        u = nxt[u][c];\n    }\n    return dem[u];\n}\n\nint main() {\n    them(\"an\"); them(\"ant\"); them(\"anh\"); them(\"bo\"); them(\"anh\");\n    cout << demTienTo(\"an\") << \" \" << demTienTo(\"anh\") << \" \" << demTienTo(\"b\") << \" \" << demTienTo(\"c\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dem",ptr:["u"],range:["0","soNut-1"]}],py:{code:"nxt = [[0] * 26]\ndem = [0]\n\ndef them(s):\n    u = 0\n    for ch in s:\n        c = ord(ch) - ord('a')\n        if nxt[u][c] == 0:\n            nxt.append([0] * 26)\n            dem.append(0)\n            nxt[u][c] = len(nxt) - 1\n        u = nxt[u][c]\n        dem[u] += 1                    # thêm một từ đi qua u\n\ndef dem_tien_to(s):\n    u = 0\n    for ch in s:\n        c = ord(ch) - ord('a')\n        if nxt[u][c] == 0:\n            return 0\n        u = nxt[u][c]\n    return dem[u]\n\nfor w in [\"an\", \"ant\", \"anh\", \"bo\", \"anh\"]:\n    them(w)\nprint(dem_tien_to(\"an\"), dem_tien_to(\"anh\"), dem_tien_to(\"b\"), dem_tien_to(\"c\"))",viz:[{type:"cells",of:"dem",ptr:["u"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static int[][] nxt = new int[20][];\n    static int[] dem = new int[20];\n    static int soNut = 1;\n\n    static void Them(string s)\n    {\n        int u = 0;\n        foreach (char ch in s)\n        {\n            int c = ch - 'a';\n            if (nxt[u][c] == 0) nxt[u][c] = soNut++;\n            u = nxt[u][c];\n            dem[u]++;                      // thêm một từ đi qua u\n        }\n    }\n\n    static int DemTienTo(string s)\n    {\n        int u = 0;\n        foreach (char ch in s)\n        {\n            int c = ch - 'a';\n            if (nxt[u][c] == 0) return 0;\n            u = nxt[u][c];\n        }\n        return dem[u];\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 20; i++) nxt[i] = new int[26];\n        foreach (string w in new[] { \"an\", \"ant\", \"anh\", \"bo\", \"anh\" }) Them(w);\n        Console.WriteLine(DemTienTo(\"an\") + \" \" + DemTienTo(\"anh\") + \" \" + DemTienTo(\"b\") + \" \" + DemTienTo(\"c\"));\n    }\n}",viz:[{type:"cells",of:"dem",ptr:["u"],range:["0","soNut-1"]}]}},{label:"Ví dụ: Liệt kê theo thứ tự từ điển",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint nxt[20][26], het[20], soNut = 1;   // nút 0 là gốc\n\nvoid them(string s) {\n    int u = 0;\n    for (char ch : s) {\n        int c = ch - 'a';\n        if (nxt[u][c] == 0) nxt[u][c] = soNut++;   // tạo nút mới\n        u = nxt[u][c];\n    }\n    het[u] = 1;                        // có một từ kết thúc ở u\n}\n\nvoid duyet(int u, string cur) {\n    if (het[u]) cout << cur << \" \";\n    for (int c = 0; c < 26; c++)                   // ký tự nhỏ đi trước\n        if (nxt[u][c]) duyet(nxt[u][c], cur + (char)('a' + c));\n}\n\nint main() {\n    them(\"to\"); them(\"tea\"); them(\"ted\"); them(\"ten\"); them(\"i\"); them(\"in\"); them(\"inn\");\n    duyet(0, \"\");\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"calls"}],py:{code:"nxt = [[0] * 26]               # nút 0 là gốc; nxt[u][c] = 0: chưa có con\nhet = [0]\n\ndef them(s):\n    u = 0\n    for ch in s:\n        c = ord(ch) - ord('a')\n        if nxt[u][c] == 0:             # tạo nút mới\n            nxt.append([0] * 26)\n            het.append(0)\n            nxt[u][c] = len(nxt) - 1\n        u = nxt[u][c]\n    het[u] = 1                         # có một từ kết thúc ở u\n\ndef duyet(u, cur, out):\n    if het[u]:\n        out.append(cur)\n    for c in range(26):                # ký tự nhỏ đi trước\n        if nxt[u][c]:\n            duyet(nxt[u][c], cur + chr(ord('a') + c), out)\n\nfor w in [\"to\", \"tea\", \"ted\", \"ten\", \"i\", \"in\", \"inn\"]:\n    them(w)\nout = []\nduyet(0, \"\", out)\nprint(*out)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[][] nxt = new int[20][];    // nút 0 là gốc; nxt[u][c] = 0: chưa có con\n    static int[] het = new int[20];\n    static int soNut = 1;\n\n    static void Them(string s)\n    {\n        int u = 0;\n        foreach (char ch in s)\n        {\n            int c = ch - 'a';\n            if (nxt[u][c] == 0) nxt[u][c] = soNut++;   // tạo nút mới\n            u = nxt[u][c];\n        }\n        het[u] = 1;                        // có một từ kết thúc ở u\n    }\n\n    static void Duyet(int u, string cur)\n    {\n        if (het[u] == 1) Console.Write(cur + \" \");\n        for (int c = 0; c < 26; c++)                   // ký tự nhỏ đi trước\n            if (nxt[u][c] != 0) Duyet(nxt[u][c], cur + (char)('a' + c));\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 20; i++) nxt[i] = new int[26];\n        foreach (string w in new[] { \"to\", \"tea\", \"ted\", \"ten\", \"i\", \"in\", \"inn\" }) Them(w);\n        Duyet(0, \"\");\n        Console.WriteLine();\n    }\n}",viz:[{type:"calls"}]}},{label:"Ví dụ: Trie nhị phân và XOR lớn nhất",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nconst int B = 5;                       // số có tối đa 5 bit\nint ch[40][2], soNut = 1;\n\nvoid them(int x) {\n    int u = 0;\n    for (int b = B - 1; b >= 0; b--) {\n        int bit = (x >> b) & 1;\n        if (ch[u][bit] == 0) ch[u][bit] = soNut++;\n        u = ch[u][bit];\n    }\n}\n\nint xorMax(int x) {                    // XOR lớn nhất của x với một số đã thêm\n    int u = 0, kq = 0;\n    for (int b = B - 1; b >= 0; b--) {\n        int bit = (x >> b) & 1;\n        if (ch[u][1 - bit]) {          // đi nhánh ngược: bit này của XOR là 1\n            kq |= 1 << b;\n            u = ch[u][1 - bit];\n        } else {\n            u = ch[u][bit];\n        }\n    }\n    return kq;\n}\n\nint main() {\n    int a[6] = {3, 10, 5, 25, 2, 8};\n    int best = 0;\n    them(a[0]);\n    for (int i = 1; i < 6; i++) {\n        best = max(best, xorMax(a[i]));\n        them(a[i]);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["x","b","bit","kq","best"]}],py:{code:"B = 5                              # số có tối đa 5 bit\nch = [[0, 0]]\n\ndef them(x):\n    u = 0\n    for b in range(B - 1, -1, -1):\n        bit = (x >> b) & 1\n        if ch[u][bit] == 0:\n            ch.append([0, 0])\n            ch[u][bit] = len(ch) - 1\n        u = ch[u][bit]\n\ndef xor_max(x):                        # XOR lớn nhất của x với một số đã thêm\n    u, kq = 0, 0\n    for b in range(B - 1, -1, -1):\n        bit = (x >> b) & 1\n        if ch[u][1 - bit]:             # đi nhánh ngược: bit này của XOR là 1\n            kq |= 1 << b\n            u = ch[u][1 - bit]\n        else:\n            u = ch[u][bit]\n    return kq\n\na = [3, 10, 5, 25, 2, 8]\nbest = 0\nthem(a[0])\nfor x in a[1:]:\n    best = max(best, xor_max(x))\n    them(x)\nprint(best)"},cs:{code:"using System;\n\nclass Program\n{\n    const int B = 5;                       // số có tối đa 5 bit\n    static int[][] ch = new int[40][];\n    static int soNut = 1;\n\n    static void Them(int x)\n    {\n        int u = 0;\n        for (int b = B - 1; b >= 0; b--)\n        {\n            int bit = (x >> b) & 1;\n            if (ch[u][bit] == 0) ch[u][bit] = soNut++;\n            u = ch[u][bit];\n        }\n    }\n\n    static int XorMax(int x)               // XOR lớn nhất của x với một số đã thêm\n    {\n        int u = 0, kq = 0;\n        for (int b = B - 1; b >= 0; b--)\n        {\n            int bit = (x >> b) & 1;\n            if (ch[u][1 - bit] != 0)       // đi nhánh ngược: bit này của XOR là 1\n            {\n                kq |= 1 << b;\n                u = ch[u][1 - bit];\n            }\n            else\n            {\n                u = ch[u][bit];\n            }\n        }\n        return kq;\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 40; i++) ch[i] = new int[2];\n        int[] a = { 3, 10, 5, 25, 2, 8 };\n        int best = 0;\n        Them(a[0]);\n        for (int i = 1; i < a.Length; i++)\n        {\n            best = Math.Max(best, XorMax(a[i]));\n            Them(a[i]);\n        }\n        Console.WriteLine(best);\n    }\n}"}},{label:"Lỗi: quên dấu kết thúc từ",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint nxt[20][26], soNut = 1;\n\nvoid them(string s) {\n    int u = 0;\n    for (char ch : s) {\n        int c = ch - 'a';\n        if (nxt[u][c] == 0) nxt[u][c] = soNut++;\n        u = nxt[u][c];\n    }\n    // thiếu: het[u] = 1;\n}\n\nbool tim(string s) {\n    int u = 0;\n    for (char ch : s) {\n        int c = ch - 'a';\n        if (nxt[u][c] == 0) return false;\n        u = nxt[u][c];\n    }\n    return true;                       // SAI: chỉ biết s là tiền tố của một từ nào đó\n}\n\nint main() {\n    them(\"cart\");\n    cout << tim(\"car\") << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["s","u","soNut"]}],py:{code:"nxt = [[0] * 26]\n\ndef them(s):\n    u = 0\n    for ch in s:\n        c = ord(ch) - ord('a')\n        if nxt[u][c] == 0:\n            nxt.append([0] * 26)\n            nxt[u][c] = len(nxt) - 1\n        u = nxt[u][c]\n    # thiếu: het[u] = 1\n\ndef tim(s):\n    u = 0\n    for ch in s:\n        c = ord(ch) - ord('a')\n        if nxt[u][c] == 0:\n            return False\n        u = nxt[u][c]\n    return True                        # SAI: chỉ biết s là tiền tố của một từ nào đó\n\nthem(\"cart\")\nprint(tim(\"car\"))",viz:[{type:"vars",names:["s","u"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static int[][] nxt = new int[20][];\n    static int soNut = 1;\n\n    static void Them(string s)\n    {\n        int u = 0;\n        foreach (char ch in s)\n        {\n            int c = ch - 'a';\n            if (nxt[u][c] == 0) nxt[u][c] = soNut++;\n            u = nxt[u][c];\n        }\n        // thiếu: het[u] = 1;\n    }\n\n    static bool Tim(string s)\n    {\n        int u = 0;\n        foreach (char ch in s)\n        {\n            int c = ch - 'a';\n            if (nxt[u][c] == 0) return false;\n            u = nxt[u][c];\n        }\n        return true;                       // SAI: chỉ biết s là tiền tố của một từ nào đó\n    }\n\n    static void Main()\n    {\n        for (int i = 0; i < 20; i++) nxt[i] = new int[26];\n        Them(\"cart\");\n        Console.WriteLine(Tim(\"car\"));\n    }\n}"}}];
